begin;
select set_config('qa.chat_a',gen_random_uuid()::text,true),set_config('qa.chat_b',gen_random_uuid()::text,true),set_config('qa.chat_c',gen_random_uuid()::text,true);
insert into auth.users(id,aud,role,email,raw_user_meta_data,created_at,updated_at)
 select id,'authenticated','authenticated',id::text||'@example.invalid','{"role_name":"传音测试"}',now(),now() from(values(current_setting('qa.chat_a')::uuid),(current_setting('qa.chat_b')::uuid),(current_setting('qa.chat_c')::uuid))u(id);
do $$
declare a uuid:=current_setting('qa.chat_a')::uuid;b uuid:=current_setting('qa.chat_b')::uuid;c uuid:=current_setting('qa.chat_c')::uuid;
 ub bigint;uc bigint;r jsonb;n integer;rid uuid:=gen_random_uuid();msg bigint;args jsonb;
begin
 assert not has_table_privilege('authenticated','moxiu_private.chat_messages','SELECT'),'private chat table denied';
 assert not has_function_privilege('authenticated','moxiu_private.chat_read(uuid)','EXECUTE'),'cannot read another inbox';
 assert not has_function_privilege('anon','public.moxiu_chat(text,jsonb)','EXECUTE'),'anonymous API denied';
 perform set_config('request.jwt.claims','{"role":"service_role"}',true);
 r:=public.moxiu_game_load(a,'{"player":{"stage":14},"stats":{"crossings":1,"wins":100},"collection":{"crops":["a","b","c"]},"beasts":{"owned":[{},{}]},"reincarnation":{"count":1}}');
 assert jsonb_array_length(r->'owned')=8,'eight earned titles automatically granted';
 assert not(r->'owned' ? 'title_creator'),'creator not automatically granted';
 perform set_config('request.jwt.claims',jsonb_build_object('role','authenticated','sub',a)::text,true);
 begin perform public.moxiu_shards('purchase',jsonb_build_object('id',gen_random_uuid(),'sku','title_creator'));raise exception 'Creator was purchasable';exception when invalid_parameter_value then null;end;
 begin perform public.moxiu_shards('equip','{"sku":"title_creator"}');raise exception 'Creator equipped without entitlement';exception when invalid_parameter_value then null;end;
 r:=public.moxiu_shards('equip','{"sku":"title_core"}');assert r->>'title'='title_core' and r->>'balance'='0','free title equipped without fragment spending';
 args:=jsonb_build_object('id',rid,'channel','public','content','你好，墨修！');r:=public.moxiu_chat('send',args);
 assert exists(select 1 from jsonb_array_elements(r->'messages')m where m->>'content'='你好，墨修！' and m->'title'->>'name'='金丹真人' and m->'title'->>'style'='gold'),'trusted equipped title in message';
 select id into msg from moxiu_private.chat_messages where sender_id=a and request_id=rid;
 r:=public.moxiu_chat('send',args);assert (select count(*) from moxiu_private.chat_messages where sender_id=a and request_id=rid)=1,'retry does not duplicate message';
 begin perform public.moxiu_chat('send',args||'{"content":"换内容"}');raise exception 'Request ID reused';exception when invalid_parameter_value then null;end;
 begin perform public.moxiu_chat('send',args||'{"title":"创世神"}');raise exception 'Client spoofed title';exception when invalid_parameter_value then null;end;
 begin perform public.moxiu_chat('send',jsonb_build_object('id',gen_random_uuid(),'channel','public','content','过快'));raise exception 'Cooldown bypass';exception when invalid_parameter_value then null;end;
 update moxiu_private.chat_messages set created_at=now()-interval '10 seconds' where sender_id=a;
 select uid into ub from public.moxiu_player_profiles where user_id=b;select uid into uc from public.moxiu_player_profiles where user_id=c;
 r:=public.moxiu_chat('send',jsonb_build_object('id',gen_random_uuid(),'channel','private','content','给乙的私聊','uid',ub));
 perform set_config('request.jwt.claims',jsonb_build_object('role','authenticated','sub',c)::text,true);
 r:=public.moxiu_chat('read','{}');assert not exists(select 1 from jsonb_array_elements(r->'messages')m where m->>'content'='给乙的私聊'),'third party cannot read private messages';
 assert not exists(select 1 from jsonb_array_elements(r->'messages')m where m->>'channel'='system'),'third party cannot read title notices';
 begin perform public.moxiu_chat('delete',jsonb_build_object('id',msg));raise exception 'Deleted another message';exception when insufficient_privilege then null;end;
 begin perform public.moxiu_chat('send',jsonb_build_object('id',gen_random_uuid(),'channel','broadcast','content','伪装公告','announcement',true));raise exception 'Nonadmin posted announcement';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claims',jsonb_build_object('role','authenticated','sub',b)::text,true);
 r:=public.moxiu_chat('read','{}');assert exists(select 1 from jsonb_array_elements(r->'messages')m where m->>'content'='给乙的私聊'),'recipient can read';
 assert not exists(select 1 from jsonb_array_elements(r->'messages')m where m ? 'sender_id' or m ? 'receiver_id' or m ? 'email'),'no internal IDs or email';
 perform set_config('request.jwt.claims',jsonb_build_object('role','authenticated','sub',a)::text,true);
 r:=public.moxiu_chat('delete',jsonb_build_object('id',msg));assert not exists(select 1 from jsonb_array_elements(r->'messages')m where (m->>'id')::bigint=msg),'owner retracts own public message';
 update moxiu_private.chat_messages set created_at=now()-interval '10 seconds' where sender_id=a;
 insert into moxiu_private.shard_admins(user_id) values(a);
 r:=public.moxiu_chat('send',jsonb_build_object('id',gen_random_uuid(),'channel','broadcast','content','测试公告','announcement',true));
 assert exists(select 1 from jsonb_array_elements(r->'messages')m where m->>'kind'='announcement' and m->>'content'='测试公告'),'admin announcement';
 update moxiu_private.chat_messages set created_at=now()-interval '10 seconds' where sender_id=a;
 begin perform public.moxiu_chat('send',jsonb_build_object('id',gen_random_uuid(),'channel','broadcast','content','太快喊话'));raise exception 'Broadcast cooldown bypass';exception when invalid_parameter_value then null;end;
 assert (select count(*) from moxiu_private.chat_messages where receiver_id=a and channel='system')=9,'one notice per earned title and one equip notice';
 perform public.moxiu_chat('read','{}');assert (select count(*) from moxiu_private.chat_messages where receiver_id=a and channel='system')=9,'reread does not grant or notify twice';
end; $$;
rollback;
select 'chat title authority, achievements, private isolation, notices, replay, rates, retraction and announcements: passed' as result;
